42:       var self = this;
43:       if (!this.keyboard || this.keyboard._hasBoundSearch) return;
44:       this.keyboard._hasBoundSearch = true;
45: 
46:       this.keyboard.addEventListener('click', function (e) {
47:         var keyBtn = e.target.closest('.key-btn');
48:         if (!keyBtn) return;
49: 
50:         var keyVal = keyBtn.getAttribute('data-key');
51:         if (keyVal === 'BACKSPACE') {
52:           self.query = self.query.slice(0, -1);
53:         } else if (keyVal === 'CLEAR') {
54:           self.query = '';
55:         } else if (keyVal === 'SPACE') {
56:           self.query += ' ';
57:         } else if (keyVal) {
58:           self.query += keyVal;
59:         }
60: 
61:         self.updateInputDisplay();
62:         self.scheduleSearch();
63:       });
64: 
65:       // SpatialNav deadend down from bottom row of keyboard escapes to search results
66:       if (global.SpatialNav && typeof global.SpatialNav.on === 'function') {
67:         global.SpatialNav.on('deadend', function (data) {
68:           if (!data) return;
69:           var curView = (global.CinejoyApp && global.CinejoyApp.state && global.CinejoyApp.state.currentView) || 'search';
70:           if (curView === 'search' && data.direction === 'down') {
71:             if (data.element && data.element.closest('.tv-keyboard-container')) {
