156:     scheduleSearch: function () {
157:       var self = this;
158:       if (this.debounceTimer) {
159:         clearTimeout(this.debounceTimer);
160:       }
161: 
162:       var clean = this.query.trim();
163:       if (!clean) {
164:         this._searchRequestId = (this._searchRequestId || 0) + 1;
165:         this.renderResults([]);
166:         if (this.resultsCount) this.resultsCount.textContent = '';
167:         return;
168:       }
169: 
170:       this.debounceTimer = setTimeout(function () {
171:         self.executeSearch();
172:       }, 300);
173:     },
174: 
175:     executeSearch: function () {
176:       var self = this;
177:       var cleanQuery = this.query.trim();
178:       if (!cleanQuery) return;
179: 
180:       if (!global.TmdbClient) {
181:         console.warn('[SearchViewController] TmdbClient unavailable for search.');
182:         return;
183:       }
184: 
185:       this._searchRequestId = (this._searchRequestId || 0) + 1;
186:       var reqId = this._searchRequestId;
187: 
188:       return global.TmdbClient.searchMulti(cleanQuery, 1).then(function (res) {
189:         if (reqId !== self._searchRequestId || self.query.trim() !== cleanQuery || !self.query.trim()) {
190:           return;
191:         }
192: 
193:         if (!res || res.error) {
194:           self.renderError();
195:           return;
196:         }
197: 
198:         var results = res.results || [];
199:         var filtered = results.filter(function (item) {
200:           return item.media_type === 'movie' || item.media_type === 'tv' || item.type === 'movie' || item.type === 'tv' || (!item.media_type && (item.title || item.name));
201:         });
202: 
203:         self.renderResults(filtered);
204:         if (self.resultsCount) {
205:           self.resultsCount.textContent = '(' + filtered.length + ' matches)';
206:         }
207:       }).catch(function (err) {
208:         if (reqId !== self._searchRequestId || self.query.trim() !== cleanQuery || !self.query.trim()) {
209:           return;
210:         }
211:         console.error('[SearchViewController] Multi-search failed:', err);
212:         self.renderError();
213:       });
214:     },
215: 
216:     renderResults: function (items) {
217:       if (!this.resultsGrid) {
218:         this.resultsGrid = document.getElementById('search-results-grid');
219:       }
220:       if (!this.resultsGrid) return;
221: 
222:       if (items.length === 0 && this.query.trim().length > 0) {
223:         this.resultsGrid.innerHTML =
224:           '<div class="search-empty-state" style="grid-column: 1 / -1; padding: 48px; text-align: center; color: rgba(255,255,255,0.6);">' +
225:             '<p style="font-size: 24px; font-weight: 500;">No results found for "' + CardFactory.escapeHtml(this.query) + '"</p>' +
226:             '<p style="font-size: 16px; margin-top: 8px;">Check spelling or try searching for another movie or television series.</p>' +
227:           '</div>';
228:         return;
229:       }
230: 
231:       var fragment = document.createDocumentFragment();
232:       for (var i = 0; i < items.length; i++) {
233:         var card = CardFactory.createPosterCard(items[i], 'search-grid', i);
234:         fragment.appendChild(card);
235:       }
236: 
237:       this.resultsGrid.innerHTML = '';
238:       this.resultsGrid.appendChild(fragment);
239:     },
240: 
241:     renderError: function () {
242:       if (!this.resultsGrid) {
243:         this.resultsGrid = document.getElementById('search-results-grid');
244:       }
245:       if (!this.resultsGrid) return;
246: 
247:       this.resultsGrid.innerHTML =
248:         '<div class="search-error-state" style="grid-column: 1 / -1; padding: 48px; text-align: center; color: #ff6b6b;">' +
249:           '<p style="font-size: 22px;">Search connection failed. Please verify TV network connection.</p>' +
250:         '</div>';
